using System.Text.Json;

namespace NomadNet.Tests;

// Actual primary f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2 observations are generated by
// GenerateNomadNetConfigurationFormVectors.py, including the real reset confirmation buttons.
[Trait("Category", "Unit")]
public sealed class NomadNetConfigurationFormTests
{
    [Fact, Trait("TestId", "T452")]
    public void EveryPrimaryEditableFieldTypeDefaultOptionAndValidatorMatchesExecutedForms()
    {
        using var fixture = NomadNetConfigurationDocumentTests.Fixture();
        var catalog = fixture.RootElement.GetProperty("catalog");
        Assert.Equal(8, catalog.GetArrayLength());
        Assert.Equal(75, NomadNetConfigurationFields.All.Count);
        foreach (var section in catalog.EnumerateArray())
        {
            var name = section.GetProperty("key").GetString()!;
            var actual = NomadNetConfigurationFields.ForSection(name);
            Assert.Equal(section.GetProperty("fields").GetArrayLength(), actual.Count);
            foreach (var expected in section.GetProperty("fields").EnumerateArray())
            {
                var field = Assert.Single(actual, item => item.Key == expected.GetProperty("key").GetString());
                Assert.Equal(expected.GetProperty("type").GetString(), field.Type);
                var value = expected.GetProperty("default");
                if (value.ValueKind == JsonValueKind.Array) Assert.Empty(field.DefaultValue.List!);
                else Assert.Equal(value.GetString(), field.DefaultValue.Scalar);
                Assert.Equal(expected.GetProperty("options").EnumerateArray().Select(item => item.GetString()), field.Options ?? []);
                Assert.Equal(expected.GetProperty("validation").EnumerateArray().Select(item => item.GetString()),
                    field.Validation.Length == 0 ? [] : new[] { field.Validation });
                Assert.Contains(field.Disposition, new[] { "runtime", "stored-only", "blocked-stack" });
            }
        }
        Assert.Equal(["respond_to_probes", "use_implicit_proof", "panic_on_interface_error"],
            NomadNetConfigurationFields.All.Where(field => field.Disposition == "blocked-stack").Select(field => field.Key));
    }

    [Fact, Trait("TestId", "T453")]
    public void ResetActualPrimaryPopulateCancelAndSaveSemanticsMatchWithoutCopyingWriterFormatting()
    {
        using var fixture = NomadNetConfigurationDocumentTests.Fixture();
        var root = fixture.RootElement;
        var initial = root.GetProperty("initial").GetString()!;
        var form = new NomadNetConfigurationForm("client", initial);
        foreach (var field in root.GetProperty("loaded").EnumerateObject()) Assert.Equal(field.Value.GetString(), form.Get(field.Name).Scalar);
        Assert.True(root.GetProperty("cancelUnchanged").GetBoolean());
        form.Set("announce_interval", new("123"));
        Assert.Throws<ArgumentException>(() => form.Reset(false));
        Assert.Equal(root.GetProperty("resetCancelledInterval").GetString(), form.Get("announce_interval").Scalar);
        var changed = form.Reset(true);
        Assert.True(root.GetProperty("resetUnsaved").GetBoolean());
        foreach (var field in root.GetProperty("reset").EnumerateObject()) Assert.Equal(field.Value.GetString(), form.Get(field.Name).Scalar);
        var saved = NomadNetConfigDocument.Parse(changed);
        foreach (var field in root.GetProperty("saved").GetProperty("client").EnumerateObject())
            Assert.Equal(field.Value.GetString(), saved.Get("client", field.Name)!.Scalar);
        Assert.Contains("# retained section comment\n", changed);
        Assert.Contains("announce_interval = 360 # retained inline", changed);
        Assert.EndsWith(initial[initial.IndexOf("[textui]", StringComparison.Ordinal)..], changed);
        Assert.Equal(initial, new NomadNetConfigurationForm("client", initial).LastText);
    }

    [Fact, Trait("TestId", "T453")]
    public void ResetMissingDefaultsAreNotMaterializedAndEmptyExistingKeysAreDeleted()
    {
        Assert.Equal("# retained\n", new NomadNetConfigurationForm("client", "# retained\n").Reset(true));
        var form = new NomadNetConfigurationForm("node", "[node]\nmax_peers = 12 # removed\nunknown = retained\n");
        var changed = form.Set("max_peers", new(""));
        Assert.Null(NomadNetConfigDocument.Parse(changed).Get("node", "max_peers"));
        Assert.Contains("unknown = retained", changed);
        Assert.Equal("[printing]\n", new NomadNetConfigurationForm("printing", "[printing]\n").Reset(true));
    }

    [Fact, Trait("TestId", "T454")]
    public void TypedBoundsErrorsAndUnsupportedStackFieldsLeaveStagedValuesHealthy()
    {
        var node = new NomadNetConfigurationForm("node", "");
        foreach (var invalid in new[] { "NaN", "Infinity", "invalid" })
            Assert.Throws<InvalidDataException>(() => node.Set("message_storage_limit", new(invalid)));
        Assert.Throws<InvalidDataException>(() => node.Set("announce_interval", new("1.5")));
        Assert.Throws<InvalidDataException>(() => node.Set("static_peers", new(new[] { "bad" })));
        Assert.Throws<InvalidDataException>(() => node.Set("node_name", new("line\ncontrol")));
        Assert.Throws<InvalidDataException>(() => node.Set("node_name", new(new string('x', 4097))));
        Assert.Throws<InvalidDataException>(() => node.Set("static_peers", new(Enumerable.Repeat(new string('a', 32), 129))));
        Assert.Throws<ArgumentException>(() => node.Set("unknown", new("bad")));
        Assert.Equal("", node.LastText);
        Assert.Contains("announce_interval = 120", node.Set("announce_interval", new("120")));
        var rns = new NomadNetConfigurationForm("reticulum", "[reticulum]\nshare_instance = no\n[interfaces]\n");
        Assert.Throws<NotSupportedException>(() => rns.Set("respond_to_probes", new("yes")));
        Assert.Throws<InvalidDataException>(() => rns.Set("shared_instance_port", new("65536")));
        Assert.Equal("no", rns.Get("respond_to_probes").Scalar);
        Assert.Contains("instance_name = synthetic", rns.Set("instance_name", new("synthetic")));
        var textui = new NomadNetConfigurationForm("textui", "");
        Assert.Throws<InvalidDataException>(() => textui.Set("glyphs", new("unknown")));
        Assert.Contains("theme = light", textui.Set("theme", new("light")));
    }

    [Fact, Trait("TestId", "T455")]
    public void ParserBudgetsMalformedValuesAndLosslessRnsMegabyteEnvelopeAreExplicit()
    {
        foreach (var malformed in new[] { "[", "[[", "[one]\nx = a,,b", "[one]\nx = 'unfinished", "[one]\nx = a\nx = b", "[one]\n[[[deep]]]\n" })
            Assert.Throws<InvalidDataException>(() => NomadNetConfigDocument.Parse(malformed));
        Assert.Throws<InvalidDataException>(() => NomadNetConfigDocument.Parse("#" + new string('a', 8192)));
        Assert.Throws<InvalidDataException>(() => NomadNetConfigDocument.Parse(string.Join("\n", Enumerable.Range(0, 2049).Select(index => $"k{index}=v"))));
        Assert.Throws<InvalidDataException>(() => NomadNetConfigDocument.Parse("#\0"));
        var large = string.Concat(Enumerable.Repeat("#" + new string('a', 999) + "\n", 70)) + "[reticulum]\nshare_instance=no\n[interfaces]\n";
        Assert.Throws<InvalidDataException>(() => NomadNetConfigDocument.Parse(large));
        var rns = new NomadNetConfigurationForm("reticulum", large);
        Assert.StartsWith(large[..large.IndexOf("[reticulum]", StringComparison.Ordinal)],
            rns.Set("enable_transport", new("yes")));
        Assert.Throws<InvalidDataException>(() => NomadNetConfigDocument.Encode(new(new[] { "line\nbreak" })));
        var repeated = "base = " + new string('x', 4000) + "\n" +
            string.Join("\n", Enumerable.Range(0, 100).Select(index => $"key{index}=%(base)s"));
        Assert.Throws<InvalidDataException>(() => NomadNetConfigDocument.Parse(repeated));
    }
}

[Trait("Category", "Integration")]
public sealed class NomadNetConfigurationStorageTests
{
    [Fact, Trait("TestId", "T456")]
    public async Task OptInExportSectionSaveRestartDisablePreservesNativeOnlyStateAndSourceText()
    {
        using var work = new Workspace();
        var settings = work.Settings with { DisplayName = "Synthetic retained name", TrustedNodes = [new string('a', 32)] };
        await settings.SaveAsync(work.Root);
        using var editor = work.Editor(settings);
        await Assert.ThrowsAsync<ArgumentException>(() => editor.SetPrimaryConfigurationAsync(true, false));
        Assert.False(File.Exists(work.Path("config")));
        await editor.SetPrimaryConfigurationAsync(true, true);
        var exported = await File.ReadAllTextAsync(work.Path("config"));
        Assert.True((await NomadNetSettings.OpenAsync(work.Root)).UsePrimaryConfiguration);
        Assert.Equal(settings.DeliveryTransferLimitBytes, (await NomadNetSettings.OpenAsync(work.Root)).DeliveryTransferLimitBytes);
        await File.AppendAllTextAsync(work.Path("config"), "[unknown]\nvalue = '''first\n# retained\nlast'''\n");
        await editor.OpenConfigurationSectionAsync("client");
        editor.SetConfigurationField("announce_interval", new("123"));
        var before = await File.ReadAllBytesAsync(work.Path("config"));
        await Assert.ThrowsAsync<ArgumentException>(() => editor.SaveConfigurationSectionAsync(false));
        Assert.Equal(before, await File.ReadAllBytesAsync(work.Path("config")));
        await editor.SaveConfigurationSectionAsync(true);
        Assert.Equal(360, settings.ClientAnnounceIntervalMinutes);
        var restarted = await NomadNetSettings.OpenAsync(work.Root);
        Assert.Equal(123, restarted.ClientAnnounceIntervalMinutes);
        Assert.Equal("Synthetic retained name", restarted.DisplayName);
        Assert.Equal(settings.TrustedNodes, restarted.TrustedNodes);
        Assert.EndsWith("[unknown]\nvalue = '''first\n# retained\nlast'''\n", await File.ReadAllTextAsync(work.Path("config")));
        await editor.CloseAsync("discard");
        Assert.Null(editor.ConfigurationForm);
        var source = await File.ReadAllBytesAsync(work.Path("config"));
        await editor.SetPrimaryConfigurationAsync(false, true);
        restarted = await NomadNetSettings.OpenAsync(work.Root);
        Assert.False(restarted.UsePrimaryConfiguration);
        Assert.Equal(123, restarted.ClientAnnounceIntervalMinutes);
        Assert.Equal(source, await File.ReadAllBytesAsync(work.Path("config")));
        Assert.Contains("enable_client = yes", exported);
        Assert.Empty(Directory.GetFiles(work.Root, ".editor-*", SearchOption.AllDirectories));
    }

    [Fact, Trait("TestId", "T457")]
    public async Task ExistingPrimarySourceNeverOverwrittenAndCancelResetConflictRecoveryAreTransactional()
    {
        using var work = new Workspace();
        await work.Settings.SaveAsync(work.Root);
        var original = "# Original selected source\r\n[client]\r\nenable_client=yes\r\nannounce_interval=90 # retained\r\n[unknown]\r\nv=keep\r\n";
        await File.WriteAllTextAsync(work.Path("config"), original);
        using var editor = work.Editor();
        await editor.SetPrimaryConfigurationAsync(true, true);
        Assert.Equal(original, await File.ReadAllTextAsync(work.Path("config")));
        await editor.OpenConfigurationSectionAsync("client");
        editor.ResetConfigurationSection(true);
        Assert.Equal(original, await File.ReadAllTextAsync(work.Path("config")));
        await editor.CloseAsync("discard");
        Assert.Null(editor.ConfigurationForm);
        Assert.Equal(90, (await NomadNetSettings.OpenAsync(work.Root)).ClientAnnounceIntervalMinutes);
        await editor.OpenConfigurationSectionAsync("client");
        editor.SetConfigurationField("announce_interval", new("120"));
        await File.AppendAllTextAsync(work.Path("config"), "# external conflict\r\n");
        var conflicted = await File.ReadAllBytesAsync(work.Path("config"));
        await Assert.ThrowsAsync<IOException>(() => editor.SaveConfigurationSectionAsync(true));
        Assert.Equal(conflicted, await File.ReadAllBytesAsync(work.Path("config")));
        await editor.CloseAsync("discard");
        await editor.OpenConfigurationSectionAsync("client");
        editor.ResetConfigurationSection(true);
        await editor.SaveConfigurationSectionAsync(true);
        Assert.Equal(360, (await NomadNetSettings.OpenAsync(work.Root)).ClientAnnounceIntervalMinutes);
        Assert.Contains("# external conflict\r\n", await File.ReadAllTextAsync(work.Path("config")));
        Assert.Empty(Directory.GetFiles(work.Root, ".editor-*", SearchOption.AllDirectories));
    }

    [Fact, Trait("TestId", "T458")]
    public async Task SelectedRnsNotPrimaryNativeFileSupportsConfirmedFormsAndPreservesCommentsInterfaces()
    {
        using var work = new Workspace();
        await work.Settings.SaveAsync(work.Root);
        var text = "# RNS selected\r\n[reticulum]\r\nshare_instance = no # retained\r\n[interfaces]\r\n";
        await File.WriteAllTextAsync(work.Path("selected-rns"), text);
        var native = await File.ReadAllBytesAsync(work.Path("settings.json"));
        using var editor = work.Editor();
        await editor.OpenConfigurationSectionAsync("reticulum");
        Assert.Equal("rns", editor.Scope);
        editor.SetConfigurationField("instance_name", new("synthetic"));
        await editor.SaveConfigurationSectionAsync(true);
        Assert.Equal(native, await File.ReadAllBytesAsync(work.Path("settings.json")));
        Assert.False(File.Exists(work.Path("config")));
        var saved = await File.ReadAllTextAsync(work.Path("selected-rns"));
        Assert.StartsWith("# RNS selected\r\n[reticulum]\r\nshare_instance = no # retained\r\n", saved);
        Assert.EndsWith("instance_name = synthetic\r\n[interfaces]\r\n", saved);
        editor.Buffer.Set("[reticulum]\nrespond_to_probes=yes\n[interfaces]\n");
        await Assert.ThrowsAnyAsync<Exception>(() => editor.SaveAsync());
        Assert.Equal(saved, await File.ReadAllTextAsync(work.Path("selected-rns")));
        Assert.Throws<InvalidOperationException>(() => editor.SetConfigurationField("enable_transport", new("yes")));
        foreach (var unsupported in new[] { "%(share_instance)s", "'''single line'''" })
        {
            editor.Buffer.Set("[reticulum]\nshare_instance=no\ninstance_name=" + unsupported + "\n[interfaces]\n");
            await Assert.ThrowsAsync<NotSupportedException>(() => editor.SaveAsync());
            Assert.Equal(saved, await File.ReadAllTextAsync(work.Path("selected-rns")));
        }
    }

    [Fact, Trait("TestId", "T459")]
    public async Task SafeguardsCancellationDisposalInvalidActivationAndMissingSourceFailWithoutOverwriteAndRecover()
    {
        using var work = new Workspace();
        var fractional = new NomadNetSettings();
        await fractional.SaveAsync(work.Root);
        using var editor = work.Editor(fractional);
        await Assert.ThrowsAsync<InvalidOperationException>(() => editor.SetPrimaryConfigurationAsync(true, true));
        Assert.False(File.Exists(work.Path("config")));
        await work.Settings.SaveAsync(work.Root);
        using var cancelled = new CancellationTokenSource();
        cancelled.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => editor.SetPrimaryConfigurationAsync(true, true, cancelled.Token));
        Assert.False(File.Exists(work.Path("config")));
        await File.WriteAllTextAsync(work.Path("config"), "[client]\nenable_client=not-a-bool\n");
        var native = await File.ReadAllBytesAsync(work.Path("settings.json"));
        await Assert.ThrowsAnyAsync<Exception>(() => editor.SetPrimaryConfigurationAsync(true, true));
        Assert.Equal(native, await File.ReadAllBytesAsync(work.Path("settings.json")));
        File.Delete(work.Path("config"));
        await editor.SetPrimaryConfigurationAsync(true, true);
        var source = await File.ReadAllBytesAsync(work.Path("config"));
        File.Delete(work.Path("config"));
        await Assert.ThrowsAsync<FileNotFoundException>(() => editor.SetPrimaryConfigurationAsync(false, true));
        await Assert.ThrowsAsync<FileNotFoundException>(() => NomadNetSettings.OpenAsync(work.Root));
        await File.WriteAllBytesAsync(work.Path("config"), source);
        await editor.OpenConfigurationSectionAsync("client");
        editor.SetConfigurationField("announce_interval", new("140"));
        var saved = await File.ReadAllBytesAsync(work.Path("config"));
        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => editor.SaveConfigurationSectionAsync(true, cancelled.Token));
        Assert.Equal(saved, await File.ReadAllBytesAsync(work.Path("config")));
        await editor.SaveConfigurationSectionAsync(true);
        Assert.Equal(140, (await NomadNetSettings.OpenAsync(work.Root)).ClientAnnounceIntervalMinutes);
        editor.Dispose();
        await Assert.ThrowsAsync<ObjectDisposedException>(() => editor.OpenConfigurationSectionAsync("client"));
    }

    [Fact, Trait("TestId", "T459")]
    public async Task SafeguardsActivePrimarySourceRejectsCompetingRuntimeWritersButSerializesRestartAndTimestampSaves()
    {
        using var work = new Workspace();
        await work.Settings.SaveAsync(work.Root);
        using var editor = work.Editor();
        await editor.SetPrimaryConfigurationAsync(true, true);
        var effective = await NomadNetSettings.OpenAsync(work.Root);
        await using var runtime = new NomadNetPropagation(work.Root, effective, () => [], _ => { },
            (_, _) => Task.FromResult(0), () => { });
        await Assert.ThrowsAsync<InvalidOperationException>(() => runtime.UpdateSettingsAsync(value => value with { NodeName = "ineffective" }));
        await runtime.RecordClientAnnounceAsync(DateTimeOffset.UnixEpoch);
        Assert.True((await NomadNetSettings.OpenAsync(work.Root)).UsePrimaryConfiguration);
        await editor.OpenConfigurationSectionAsync("client");
        editor.SetConfigurationField("announce_interval", new("180"));
        await runtime.SaveConfigurationForRestartAsync(token => editor.SaveConfigurationSectionAsync(true, token));
        Assert.True(runtime.ConfigurationRestartPending);
        var native = await File.ReadAllBytesAsync(work.Path("settings.json"));
        await runtime.RecordClientAnnounceAsync(DateTimeOffset.UnixEpoch.AddDays(1));
        Assert.Equal(native, await File.ReadAllBytesAsync(work.Path("settings.json")));
        Assert.Equal(360, runtime.Settings.ClientAnnounceIntervalMinutes);
        Assert.Equal(180, (await NomadNetSettings.OpenAsync(work.Root)).ClientAnnounceIntervalMinutes);
    }

    private sealed class Workspace : IDisposable
    {
        public string Root { get; } = System.IO.Path.GetFullPath(System.IO.Path.Combine("artifacts", "tests", "nomad-config-forms", "managed-" + Guid.NewGuid().ToString("N")));
        public NomadNetSettings Settings { get; } = new() { NodePageRefreshIntervalMinutes = 0, NodeFileRefreshIntervalMinutes = 0 };
        public Workspace() => Directory.CreateDirectory(Root);
        public string Path(string name) => System.IO.Path.Combine(Root, name);
        public NomadNetEditor Editor(NomadNetSettings? settings = null) => new(Root, settings ?? Settings, Path("selected-rns"));
        public void Dispose() => Directory.Delete(Root, recursive: true);
    }
}
